#!/usr/bin/env bash
# setup: platform auto-detect + docker-compose.override.yml generation

cmd_setup() {
  local root_dir
  root_dir="$(cd "${SCRIPT_DIR}/.." && pwd)"
  local override_file="${root_dir}/docker-compose.override.yml"

  local arch platform
  arch="$(uname -m)"
  case "$arch" in
    arm64|aarch64) platform="linux/arm64" ;;
    x86_64|amd64)  platform="linux/amd64" ;;
    *) echo -e "${RED}Unknown architecture: $arch${NC}"; exit 1 ;;
  esac

  echo -e "${GREEN}Detected architecture: $arch → $platform${NC}"

  cat > "$override_file" << EOF
# Auto-generated by: bash runtime/ci.sh setup
# Arch: $arch → Platform: $platform
# Do not edit manually — re-run 'ci.sh setup' to regenerate.
services:
  api:
    platform: $platform
  horizon:
    platform: $platform
  scheduler:
    platform: $platform
  reverb:
    platform: $platform
  migrator:
    platform: $platform
  migrator-fresh:
    platform: $platform
EOF

  echo "Created: docker-compose.override.yml"
  echo "Now run: docker compose up -d --build"
}
